--
-- TOC entry 726 (class 1255 OID 43073)
-- Name: assert_leader_rank(); Type: FUNCTION; Schema: clan; Owner: lost_kingsland
--

CREATE FUNCTION clan.assert_leader_rank() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_clan_id uuid;
BEGIN
    IF TG_TABLE_NAME = 'clans' THEN
        target_clan_id := NEW.id;
    ELSE
        target_clan_id := COALESCE(NEW.clan_id, OLD.clan_id);
    END IF;
    IF EXISTS (SELECT 1 FROM clan.clans c WHERE c.id = target_clan_id)
       AND NOT EXISTS (
           SELECT 1 FROM clan.clans c
           JOIN clan.clan_members m ON m.clan_id=c.id AND m.player_id=c.leader_player_id
           WHERE c.id=target_clan_id AND m.rank='LEADER'
       ) THEN
        RAISE EXCEPTION 'clan leader_player_id must identify the LEADER-ranked member';
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION clan.assert_leader_rank() OWNER TO lost_kingsland;

--
-- TOC entry 629 (class 1255 OID 42351)
-- Name: can_receive_rarity(inventory.item_rarity, inventory.item_rarity); Type: FUNCTION; Schema: market; Owner: lost_kingsland
--

CREATE FUNCTION market.can_receive_rarity(p_item_rarity inventory.item_rarity, p_natural_max inventory.item_rarity) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT item.power_ordinal <= LEAST(natural_policy.power_ordinal + 1, global_max.max_ordinal)
    FROM inventory.rarity_policy item
    JOIN inventory.rarity_policy natural_policy ON natural_policy.rarity = p_natural_max
    CROSS JOIN (SELECT max(power_ordinal) AS max_ordinal FROM inventory.rarity_policy) global_max
    WHERE item.rarity = p_item_rarity;
$$;


ALTER FUNCTION market.can_receive_rarity(p_item_rarity inventory.item_rarity, p_natural_max inventory.item_rarity) OWNER TO lost_kingsland;

