--
-- TOC entry 431 (class 1259 OID 46627)
-- Name: v_adventure_floor_balance; Type: VIEW; Schema: admin; Owner: lost_kingsland
--

CREATE VIEW admin.v_adventure_floor_balance AS
 SELECT config.version_code,
    profile.min_floor,
    profile.max_floor,
    profile.max_natural_rarity,
    profile.rarity_weights,
    profile.item_level_rule,
    profile.monster_profile,
    rules.enemy_count_bands,
    rules.normalization,
    rules.sub_stage_targets,
    rules.reference_player_model
   FROM ((content.exploration_floor_profiles profile
     JOIN platform.config_versions config ON ((config.id = profile.config_version_id)))
     LEFT JOIN content.section_rules rules ON ((rules.config_version_id = profile.config_version_id)));


ALTER VIEW admin.v_adventure_floor_balance OWNER TO lost_kingsland;

