--
-- TOC entry 459 (class 1259 OID 47176)
-- Name: v_character_catalog; Type: VIEW; Schema: admin; Owner: lost_kingsland
--

CREATE VIEW admin.v_character_catalog AS
 SELECT d.code,
    d.config_version_id,
    d.display_name_vi,
    d.rarity,
    d.combat_role,
    d.affinity_code,
    d.weapon_theme,
    d.rarity_power_mult,
    d.stat_profile,
    d.signature_skill_vi,
    d.lore_summary_vi,
    d.image_asset_key,
    d.active,
    r.power_ordinal AS rarity_ordinal
