    s.activation_count,
    s.reference_section,
    s.last_attempt_at,
    s.last_killed_at,
    s.updated_at,
    c.display_name_vi,
    LEAST(30.0, ((COALESCE(m.victory_count, 0))::numeric * 3.0)) AS mastery_hp_bonus_pct,
    LEAST(18.0, ((COALESCE(m.victory_count, 0))::numeric * 1.8)) AS mastery_damage_bonus_pct,
