   FROM ((adventure.player_faction_boss_state s
     LEFT JOIN adventure.faction_boss_catalog c ON (((c.boss_code)::text = (s.current_boss_code)::text)))
     LEFT JOIN adventure.faction_boss_mastery m ON (((m.player_id = s.player_id) AND ((m.boss_code)::text = (s.current_boss_code)::text))));


