--
-- TOC entry 417 (class 1259 OID 45488)
-- Name: v_economy_reconciliation; Type: VIEW; Schema: ops; Owner: lost_kingsland
--

CREATE VIEW ops.v_economy_reconciliation AS
 SELECT a.id AS account_id,
    a.owner_scope,
    a.owner_id,
    a.asset_code,
    a.available_balance AS stored_balance,
    COALESCE(last_entry.balance_after, (0)::numeric) AS ledger_balance,
    (a.available_balance - COALESCE(last_entry.balance_after, (0)::numeric)) AS discrepancy
   FROM (economy.ledger_accounts a
     LEFT JOIN LATERAL ( SELECT e.balance_after
           FROM economy.ledger_entries e
          WHERE (e.ledger_account_id = a.id)
          ORDER BY e.account_sequence DESC
         LIMIT 1) last_entry ON (true));


ALTER VIEW ops.v_economy_reconciliation OWNER TO lost_kingsland;

--
-- TOC entry 418 (class 1259 OID 45493)
-- Name: v_item_ownership_reconciliation; Type: VIEW; Schema: ops; Owner: lost_kingsland
--

CREATE VIEW ops.v_item_ownership_reconciliation AS
 SELECT id AS item_id,
    owner_player_id,
    state,
    ( SELECT e.to_player_id
           FROM inventory.item_ownership_events e
          WHERE (e.item_instance_id = i.id)
          ORDER BY e.sequence_no DESC
         LIMIT 1) AS history_owner_id,
    (EXISTS ( SELECT 1
           FROM market.item_reservations r
          WHERE (r.item_instance_id = i.id))) AS has_active_lock
   FROM inventory.item_instances i;


ALTER VIEW ops.v_item_ownership_reconciliation OWNER TO lost_kingsland;

